/* @lc app=leetcode id=2584 lang=kotlin */ class Solution { fun findValidSplit(nums: IntArray): Int = { num: Int -> (2..1000).fold(num to mutableListOf<Int>()) { (x, list), d -> if (x % d == 0) list.add(d).let { generateSequence(x) { if (it % d == 0) it / d else null }.last() to list } else x to list }.let { (x, list) -> if (x > 1) list.also { list.add(x) } else list } }.let { factors -> mutableMapOf<Int, Int>().also { lastMap -> nums.indices.forEach { i -> factors(nums[i]).forEach { p -> lastMap[p] = i } } }.let { last -> (0 until nums.size - 1).fold(-1 to 0) { (ans, maxR), i -> if (ans != -1) ans to maxR else factors(nums[i]).fold(maxR) { currMax, p -> maxOf(currMax, last[p]!!) }.let { nxtMax -> if (nxtMax == i) i to nxtMax else -1 to nxtMax } }.first } } }